CREATE INDEX idx_uso_source ON public.unified_signal_outcomes USING btree (signal_source);
CREATE INDEX idx_uso_symbol_date ON public.unified_signal_outcomes USING btree (symbol, signal_date);
CREATE UNIQUE INDEX uq_unified_signal_outcomes_unified_signal_id_horizon_days ON public.unified_signal_outcomes USING btree (unified_signal_id, horizon_days);

-- ── unified_signals ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "unified_signals" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "symbol" TEXT NOT NULL,
  "signal_date" TIMESTAMPTZ DEFAULT now(),
  "signal_source" TEXT NOT NULL,
  "signal_type" TEXT NOT NULL,
  "entry_price" DOUBLE PRECISION,
  "target_price" DOUBLE PRECISION,
  "stop_loss" DOUBLE PRECISION,
  "confidence_score" DOUBLE PRECISION,
  "reasoning" TEXT,
  "technical_score" DOUBLE PRECISION,
  "quant_score" DOUBLE PRECISION,
  "ai_reasoning" TEXT,
  "status" TEXT DEFAULT 'ACTIVE'::text,
  "signal_generated_at" TIMESTAMPTZ NOT NULL,
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "screener_momentum_score" REAL,
  "screener_tier1_count" REAL,
  "screener_cat_breadth" REAL,
  UNIQUE ("symbol", "signal_source", "signal_type", "signal_date")
);
CREATE INDEX idx_unified_signals_date ON public.unified_signals USING btree (signal_date DESC);
CREATE INDEX idx_us_confidence ON public.unified_signals USING btree (confidence_score DESC);
CREATE INDEX idx_us_source ON public.unified_signals USING btree (signal_source);
CREATE INDEX idx_us_status ON public.unified_signals USING btree (status);
CREATE INDEX idx_us_symbol_date ON public.unified_signals USING btree (symbol, signal_date DESC);
CREATE UNIQUE INDEX idx_us_unique_key ON public.unified_signals USING btree (symbol, signal_source, signal_type, signal_date);
CREATE UNIQUE INDEX uq_unified_signals_symbol_signal_source_signal_type_signal_date ON public.unified_signals USING btree (symbol, signal_source, signal_type, signal_date);

-- ── url_endpoints ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "url_endpoints" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "template" TEXT NOT NULL,
  "host" TEXT,
  "path_skeleton" TEXT,
  "param_keys" TEXT,
  "method" TEXT DEFAULT 'GET'::text,
  "n_urls" INTEGER DEFAULT 0,
  "last_run_at" TEXT,
  "last_status" TEXT,
  UNIQUE ("template")
);

-- ── url_fetches ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "url_fetches" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "endpoint_id" INTEGER NOT NULL,
  "concrete_url" TEXT,
  "params_json" TEXT,
  "fetched_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  "http_status" INTEGER,
  "latency_ms" INTEGER,
  "ok" INTEGER,
  "response_bytes" INTEGER,
  "raw_json" TEXT,
  "error" TEXT
);
CREATE INDEX ix_url_fetches_ep ON public.url_fetches USING btree (endpoint_id, fetched_at);

-- ── url_field_correlations ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "url_field_correlations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "endpoint_id" INTEGER NOT NULL,
  "run_at" TEXT,
  "field_path" TEXT,
  "target" TEXT,
  "n" INTEGER,
  "pearson" REAL,
  "spearman" REAL,
  "ic" REAL
);

-- ── url_fields ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "url_fields" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "endpoint_id" INTEGER NOT NULL,
  "run_at" TEXT,
  "field_path" TEXT,
  "dtype" TEXT,
  "fill_rate" REAL,
  "cardinality" INTEGER,
  "num_min" REAL,
  "num_max" REAL,
  "num_mean" REAL,
  "universe_overlap_pct" REAL,
  "changed_vs_last" INTEGER
);
CREATE INDEX ix_url_fields_ep ON public.url_fields USING btree (endpoint_id, run_at);

-- ── url_params ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "url_params" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "endpoint_id" INTEGER NOT NULL,
  "name" TEXT,
  "location" TEXT,
  "inferred_type" TEXT,
  "is_variable" INTEGER,
  "distinct_count" INTEGER,
  "sample_values" TEXT,
  UNIQUE ("endpoint_id", "location", "name")
);

-- ── users ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "users" (
  "id" TEXT NOT NULL PRIMARY KEY,
  "email" TEXT,
  "name" TEXT,
  "photoURL" TEXT,
  "createdAt" TIMESTAMPTZ DEFAULT now(),
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "updated_at" TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX idx_users_created_at ON public.users USING btree (created_at DESC);

-- ── watchlist ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "watchlist" (
  "userId" TEXT NOT NULL,
  "symbol" TEXT NOT NULL,
  "addedAt" TIMESTAMPTZ DEFAULT now(),
  "price" DOUBLE PRECISION,
  "name" TEXT,
  "source" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT now(),
  "updated_at" TIMESTAMPTZ DEFAULT now(),
  PRIMARY KEY ("userId", "symbol")
);
CREATE INDEX idx_watchlist_created_at ON public.watchlist USING btree (created_at DESC);
CREATE INDEX idx_watchlist_userid ON public.watchlist USING btree ("userId");

-- ── working_capital_history ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "working_capital_history" (
  "symbol" TEXT NOT NULL,
  "fiscal_year" TEXT NOT NULL,
  "receivables_days" DOUBLE PRECISION,
  "inventory_days" DOUBLE PRECISION,
  "payables_days" DOUBLE PRECISION,
  "ccc" DOUBLE PRECISION,
  "revenue_fy" DOUBLE PRECISION,
  "cogs_proxy_fy" DOUBLE PRECISION,
  "fetched_at" TEXT DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("symbol", "fiscal_year")
);
CREATE INDEX idx_wch_sym ON public.working_capital_history USING btree (symbol, fiscal_year DESC);

-- ── xgboost_predictions ─────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS "xgboost_predictions" (
  "symbol" TEXT NOT NULL PRIMARY KEY,
  "prediction_date" TEXT NOT NULL,
  "xgboost_score" DOUBLE PRECISION,
  "signal" TEXT,
  "is_growth" BIGINT,
  "is_value" BIGINT,
  "is_quality" BIGINT,
  "is_breakout" BIGINT,
  "is_pullback" BIGINT,
  "feature_breakdown" TEXT,
  "created_at" TIMESTAMPTZ DEFAULT now()
);
CREATE INDEX idx_xgb_score ON public.xgboost_predictions USING btree (xgboost_score DESC);


-- ── Timescale hypertables / compression / retention ──────────────────────
SELECT create_hypertable('confluence_signals', 'computed_at', chunk_time_interval => INTERVAL '7 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE confluence_signals SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('confluence_signals', INTERVAL '30 days', if_not_exists => TRUE);
SELECT add_retention_policy('confluence_signals', INTERVAL '90 days', if_not_exists => TRUE);
SELECT create_hypertable('feature_store', 'date', chunk_time_interval => INTERVAL '90 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE feature_store SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('feature_store', INTERVAL '120 days', if_not_exists => TRUE);
SELECT create_hypertable('intraday_ohlcv', 'datetime', chunk_time_interval => INTERVAL '7 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE intraday_ohlcv SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('intraday_ohlcv', INTERVAL '30 days', if_not_exists => TRUE);
SELECT add_retention_policy('intraday_ohlcv', INTERVAL '365 days', if_not_exists => TRUE);
SELECT create_hypertable('macro_asset_prices', 'date', chunk_time_interval => INTERVAL '365 days', if_not_exists => TRUE, migrate_data => TRUE);
SELECT create_hypertable('stock_ohlcv', 'date', chunk_time_interval => INTERVAL '90 days', if_not_exists => TRUE, migrate_data => TRUE);
ALTER TABLE stock_ohlcv SET (timescaledb.compress, timescaledb.compress_segmentby = 'symbol');
SELECT add_compression_policy('stock_ohlcv', INTERVAL '180 days', if_not_exists => TRUE);
